import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { useParams } from 'react-router-dom';

const AtividadeList = () => {
  const [atividades, setAtividades] = useState([]);
  const [loading, setLoading] = useState(true);
  const [atividade, setAtividade] = useState({
    nome: '',
    descricao: '',
  });
  const [atividadeMessage, setAtividadeMessage] = useState('');
  const [creatingAtividade, setCreatingAtividade] = useState(false);
  const { clienteId, projetoId } = useParams(); // Pegando o clienteId e projetoId da URL

  // Fetch atividades when the component mounts or projetoId changes
  useEffect(() => {
    const fetchAtividades = async () => {
      try {
        const response = await axios.get(
          `http://localhost:8080/clientes/${clienteId}/projetos/${projetoId}/atividades`
        );
        setAtividades(response.data);
      } catch (err) {
        console.error('Erro ao carregar atividades', err);
      } finally {
        setLoading(false);
      }
    };

    fetchAtividades();
  }, [clienteId, projetoId]);

  const handleAtividadeChange = (e) => {
    const { name, value } = e.target;
    setAtividade((prev) => ({ ...prev, [name]: value }));
  };

  const handleCreateAtividade = async () => {
    try {
      const response = await axios.post(
        `http://localhost:8080/clientes/${clienteId}/projetos/${projetoId}/atividades`,
        atividade
      );
      setAtividadeMessage('Atividade criada com sucesso!');
      setAtividade({ nome: '', descricao: '' }); // Limpar formulário após criação
      setAtividades((prevAtividades) => [...prevAtividades, response.data]); // Atualizar a lista de atividades
      setCreatingAtividade(false); // Fechar formulário de criação
    } catch (err) {
      console.error('Erro ao criar atividade', err);
      setAtividadeMessage('Erro ao criar atividade');
    }
  };

  return (
    <div className="atividade-list">
      <h3>Atividades do Projeto</h3>

      {/* Exibindo a mensagem após criação */}
      {atividadeMessage && <p>{atividadeMessage}</p>}

      {loading ? (
        <p>Carregando...</p>
      ) : (
        <div>
          <ul>
            {atividades.length === 0 ? (
              <p>Não há atividades para este projeto.</p>
            ) : (
              atividades.map((atividade) => (
                <li key={atividade.id}>
                  <h4>{atividade.nome}</h4>
                  <p>{atividade.descricao}</p>
                </li>
              ))
            )}
          </ul>

          {/* Exibir o formulário de criação de atividade */}
          {creatingAtividade ? (
            <div className="form-criar-atividade">
              <h4>Criar Atividade</h4>
              <input
                type="text"
                name="nome"
                value={atividade.nome}
                placeholder="Nome da Atividade"
                onChange={handleAtividadeChange}
              />
              <textarea
                name="descricao"
                value={atividade.descricao}
                placeholder="Descrição da Atividade"
                onChange={handleAtividadeChange}
              />
              <button onClick={handleCreateAtividade}>Criar Atividade</button>
              <button onClick={() => setCreatingAtividade(false)}>Cancelar</button>
            </div>
          ) : (
            <button onClick={() => setCreatingAtividade(true)}>
              Adicionar Atividade
            </button>
          )}
        </div>
      )}
    </div>
  );
};

export default AtividadeList;
